        "text": "Здесь же поясняется трёхчастная классификация «собраний» (курсов) басти — по числу процедур (карма), по срокам (кала) и по сочетанию (йога). При «карма»-собрании полагается тридцать басти: сперва один масляный (Анувасана), затем пять Нируха-васти чередуются с масляными, далее — двенадцать Анувасана-васти вперемешку с Нирухами. При «кала»-собрании — три Нируха в начале срока, один Анувасана в конце, а между ними шесть Нируха, перемежаемых Анувасана-васти. При «йога»-собрании даются лишь три Нируха-васти и пять Анувасана-васти — по одному в начале и в конце, а прочие — в середине курса."
