        "text": "Теперь (изложим правило для) того, кто должным образом умащён маслом, прошёл потогонную процедуру, покойно провёл сон, а пища у него уже переварилась (далее фрагмент повреждён). Из данти, шьямы, кампиллаки, нилики, сапталы, вачи и вишаники (тех, что удастся собрать), взятых по одной карше или половине палы, готовят отвар в одном-двух прастхах воды, выпаривая до четвёртой части (фрагмент повреждён); добавив коровью мочу, дают пить не слишком жидким, не слишком горячим и не слишком холодным, сообразуясь со временем, силой, возрастом и болезнью. Младенца же, как и прежде, поят с руки либо дают это (средство) слизать вместе со свежим маслом (навонитой) (фрагмент повреждён)... одна, две или три прастхи (жидкости выходит при должной мере). Свыше этого называют избыточным действием (атийогой). И в этом случае весь уход такой же, как после рвотного средства."
