        "text": "Утомление, слабость, уныние, помрачение сознания, потеря памяти и слуха, невнятность речи, бред, угроза жизни (кровотечение), боль в области желудка, головокружение (фрагмент повреждён); сухость во рту и в сердце, спазм шеи, судороги в боку, дрожь сердца, сухость волос, лица и кожи тела; боль в пояснице, мочевом пузыре и паху; жжение полового члена; боль, нагноение и выпадение прямой кишки; понос; дрожь бёдер; боль в коленях и голенях (фрагмент повреждён) — таковы тяжкие недуги, возникающие от избыточного действия (атийоги) очистительных средств."
