        "text": "Если человеку с крутым (трудноподатливым) кишечником, не получившему должного умащения, дают слабое и мягкое лекарство (фрагмент повреждён), у него возникают насморк, вздутие живота и обильное слюнотечение от Капхи. Если же лекарство дают при обострении Капхи, при лихорадке или поносе, — от слабого и малого лекарства возникает задержка (стула). От чрезмерного же слабительного действия — выпадение прямой кишки, обострение Ваты, потеря сознания (фрагмент повреждён), режущие боли. У того, кто лишён умащения и потогонного очищения, и кому дают лекарство при непереваренной пище, возникают дизентерийные тенезмы, боль, рвота, икота, вздутие, одышка, кашель, отсутствие аппетита и тошнота. У чрезмерно же умащённого возникают боль, вялость, сонливость, истечения из прямой кишки, головная боль (фрагмент повреждён), жжение, стягивание губ, ослабление пищеварительного огня и чахотка (якшма)."
