        "text": "«Посему, о Владыка, поведай о начале применения лекарств. Что служит основой (адхиштхана) лекарства? Как преподаётся знание о лекарстве и понятия «бхешаджа», «бхайшаджья», «агада» и «кашая»? Хотя в каждом веществе побочно присутствуют все вкусы, но по преобладанию один вкус зовётся главным — так, в солодке (мадхука) преобладает сладкий вкус, в кападже (кайтха) — кислый, в каменной соли (сайндхава) — солёный, в сухом имбире (нагара) — острый, в тиктарохини — горький, а в харитаки (абхая) — вяжущий. Раз вкусы столь различны, отчего же их сочетание именуют единым словом «кашая» — какова тому причина? Сколько качеств у лекарства и сколько его разновидностей? Сколько сроков приёма лекарства и каков порядок для каждого срока? В каком состоянии лекарство пить должно, а в каком — нет? Как надлежит его пить и чего избегать после приёма? Каковы признаки ещё перевариваемого и уже переваренного лекарства? Как, разделив возраст на периоды, определяют дозу (матра)? Какова доза, усмиряющая дошу через нижние и через верхние пути, какова доза животворящая (дживания), разжигающая (дипания), очистительная (шамшодхана) и какова доза масла (снеха)? Всё это поведай мне по истине, о великий мудрец, — от новорождённого младенца и вплоть до ста лет жизни!»"
