        "text": "Эти сроки приёма лекарства следует, таким образом, различать десятикратно. Не следует давать лекарство: тому, чьи ткани (дхату) и чувства истощены; тому, кто спокоен (удовлетворён), утомлён, изнурён или голоден; тому, чей кишечник уже «сожжён» предыдущим лекарством; тому, кто разгневан, удручён или охвачен горем; тому, кто бодрствовал ночью; тому, чья пища испортилась или у кого несварение (аджирна); тому, кто изнурён чрезмерным трудом или тяжестью; тому, кому недавно поставлена нируха- или анувасана-васти; тому, кто постился; тому, кому дано слабительное (виречана); тому, кто ест без разбора всё, что попадётся; тому, кто в обмороке или измучен жарой; тому, кто только что напился воды. Равно не следует давать лекарство, противоречащее текущему состоянию больного."
