        "text": "Знающему врачу следует отвергать лекарство: которое несоразмерно (недостаточно или избыточно) относительно болезни, доши, силы и огня пищеварения больного; которое им прежде не было изучено; которое лишено предписанных качеств; которое не соответствует природе болезни или переносимости (сатмья) больного; которое дурно приготовлено или неприятно уму больного; и то, после приёма и переваривания которого хотя бы малейший след доши всё ещё заметен, а болезнь не убывает."
