        "text": "14. От чрезмерно горячей пищи обжигаются язык, горло, губы, сердце и живот; вкус пищи не ощущается, и возникают тяжкие недуги: воспаление во рту, воспаление глаз, висарпа (рожистое воспаление), рактапитта (кровоточивость от расстройства Питты), головокружение и лихорадка."
