        "text": "Человеку с крепким пищеварительным огнём, неподатливым кишечником и обилием дош, у которого возник удаварта (задержка ветров и кала), врач должен сначала вывести кал с помощью свечей (пхалаварти), затем хорошо промаслить и пропотить его тело, и лишь после этого дать слабительное."
