        "text": "Учитывая то или иное состояние, зависящее от доша, времени и силы (больного), врач может увеличивать или уменьшать число клизм либо количество входящих в них веществ. В курсе йогабасти уместно увеличение, в курсе кармабасти — уменьшение, а в курсе калабасти — и то и другое, смотря по силе или слабости доша."
