        "text": "При болезнях вāты нирӯха-басти готовится с равной долей масла, тёплым и умащающим — даётся одна клизма. При болезнях питты — с шестой долей масла и молоком, сладкая и охлаждающая, — даются две клизмы. При болезнях капхи — с восьмой долей масла и коровьей мочой, острая и горячая, — даются три клизмы. Одна такая клизма при вāте изгоняет дошу из вместилищ (кoштхи); при питте — две, при капхе — три; сверх этого числа клизмы давать не следует."
