        "text": "После басти рекомендуется соответственно давать пищу: мясной отвар (при вāте), молоко (при питте) и суп (при капхе); либо же питание назначается сообразно силе больного, времени, состоянию агни (пищеварительного огня), местности, природе (пракрити) и привычному укладу (сатмья)."
