        "text": "Клизмы всегда следует давать в нечётном числе, никогда — в чётном. Нечётные недуги побеждаются именно нечётным числом клизм: при болезни капхи — одна или три, при болезни питты — пять или семь, при болезни вāты — девять или одиннадцать. У того, кто получает такое (нечётное) число клизм, доша и дхату пребывают в равновесии. (Это правило нечётности относится прежде всего к самостоятельно проводимой анувасане; для анувасаны, входящей составной частью в курс нирӯхи, оно не обязательно — там допустимо и чётное число.)"
