        "text": "Тому, кому через три дня была дана анувасана, спустя неделю следует дать басти курса карма или кала. Затем, вновь проведя асthапану (нирӯха-басти) и умастив и прогрев тело, — если наутро натощак в кoштхе обнаруживается неусвоенный āма, а конечности были хорошо разминающе помассированы, — на пятый день следует дать йогабасти."
