        "text": "Нирӯха-басти не следует готовить ни чрезмерно холодной, ни чрезмерно горячей, ни чрезмерно острой, ни, напротив, чрезмерно мягкой; ни чрезмерно сухой, ни чрезмерно жирной; ни чрезмерно густой, ни чрезмерно жидкой; ни в чрезмерно большом, ни в чрезмерно малом количестве."
