        "text": "(Правильно применённая нирӯха-басти) сохраняет возраст (продлевает молодость), усиливает половую силу, улучшает голос, цвет лица, силу и агни, выводит из тела вāту, питту, капху и отходы (мала); у детей, стариков и людей среднего возраста она быстро и значительно прибавляет бодрости, придаёт ясность всем органам чувств и смягчает тело. Так были изложены достоинства и недостатки нирӯха-басти."
