        "text": "Признаки правильного действия (сам-йога) нирӯхи: когда последовательно выходят кал, вāта, питта и капха, а затем — пена, подобная (по цвету) раковине или горному хрусталю; у тех, кому клизма проведена правильно, возникает глубокая мягкость тела, появляется желание есть, лёгкость, ясность и мягкость тела, свободное отхождение кала, мочи и газов, а также прояснение всех органов чувств."
