        "text": "При аёге (недостаточном действии клизмы) наблюдается всё противоположное указанному. При атийоге (избыточном действии) — чрезмерное выделение капхи, питты, крови или жидкости, подобной промывным водам от мяса, а также икота, дрожь, жажда, слабость, ломота в теле, помрачение сознания, изнеможение, бессонница и бред."
