        "sanskrit": "स्नेहप्रमाणं यद्बस्तौ निरूहस्त्रिगुणस्ततः । अतिव्यवायव्यायामपानयानाध्वसङ्गिनः ॥१०९॥ वयस्थाः स्नेहसात्म्याश्च येषां चाग्निबलं दृढम्‌ । येषां चाधः प्रकुपितो वायुर्वातात्मकाश्च ये ॥११०॥ तेषूत्तमां प्रणिदधेत्‌ स्नेहमात्रां विचक्षणः । य एभ्यो मध्यमावस्थाः पुरुषास्तेषु मध्यमाम्‌ ॥१११॥ वयोव्याधिबलावेक्षामितरामितरेषु च । इति कर्मादिबस्तीनां त्रितयं समुदाहृतम्‌ ॥११२॥",
        "text": "Тем, кто предаётся чрезмерному соитию, физическим упражнениям, питью (вина), езде и долгим переходам, кто пребывает в зрелом возрасте, для кого масло привычно (сатмья), у кого крепка сила агни, у кого вāта возмущена в нижней части тела, и кто по природе своей склонен к вāте, — таким сведущий врач должен назначать высшую меру масла. Тем же, кто занимает среднее положение по этим признакам, — среднюю меру, а прочим — меньшую, смотря по возрасту, болезни и силе. Так были изложены все три вида басти — карма, кала и йога."
