        "text": "Тот, кто лечит гулму как зародыш или зародыш как гулму, покрывает себя бесславием и грехом. Поэтому при возникшем сомнении следует применять лишь общие для обоих состояний меры; никакой врач не должен приступать к лечению нераспознанной болезни."
