        "text": "Знающий доши и искусный в лечении врач должен дать больной испить кальянака-гхриту, панчагавья-гхриту, шатпала-гхриту либо тиктака-гхриту; резкими средствами провести ей Астхапана-васти, затем разумно — Анувасана-васти, а также кормить её полезной пищей: молоком, юшей и мясным отваром."
