        "text": "В этот же (шестой) месяц врачевателю следует ввести кормление ребёнка различными плодами. Когда же прорезались зубы — обычно на десятом месяце, в день, отмеченный созвездием Праджапати и благоприятный, — почтив божеств, удовлетворив брахманов мясной пищей вместе с дарами (дакшиной), произнеся благопожелание, на обмазанном коровьим навозом жертвеннике разложив траву дарбха и рассыпав по ней цветы жасмина, следует в четырёх местах поставить украшенные благовониями и гирляндами полные сосуды с водой и знаки свастики, приготовить, как и прежде, все принадлежности для (обряда с) игрушками, а посреди (всего этого) положить пищу и питьё, приготовленные из мяса перепёлки, воробья, куропатки или петуха (одного из них), а также из иных, различно и искусно приготовленных, приятных кушаний. Затем врачевателю, обратившись лицом на восток, следует усадить ребёнка — омытого, наряженного, облачённого в новые одежды и над которым уже совершён обряд защиты — лицом на запад, разжечь огонь и, взяв пищу со всеми приправами, совершить возлияние со следующей мантрой."
