        "text": "Когда же [телесная] основа не повреждена — будь то наяву или во сне, — [огонь], побуждаемый самана-ваю через дыхание вдоха и выдоха (12), и раздуваемый удана-ваю, пачака-агни переваривает пищу должным образом. Так изложено происхождение [этой болезни]; далее я изложу её признаки (13)."
