        "sanskrit": "व्याधिरामाशयोत्थोऽयं कफपित्ते तदाश्रये । तस्मादादित एवास्य मूलच्छेदाय बुद्धिमान्‌ ॥१८॥ अक्षीणबलमांसस्य वमनं संप्रकल्पयेत्‌ । नान्यो मान्यः क्रमो ह्यस्य शान्तये वमनादृते ॥१९॥ मूलच्छेदादिव तरोः स्कन्धशाखाविपर्यये । बान्तस्य यः स्यात्तदनुबन्धकृत्‌ ॥२०॥",
