        "text": "Для укрепления времени [благоприятного для лечения], пищеварительного огня и телесной силы [полезны] чеснок, харитаки, пиппали, топлёное масло, а также выдержанное вино (41); [при этом] следует избегать перечисленных выше причин этой болезни. У того, кто придерживается подобающего образа питания и поведения, занимается надлежащими упражнениями (42), не подвержен пристрастию к вкусу (языколюбию), владеет собой и является человеком достойным, — эта шуктака (амлапитта) стихает."
