        "text": "У того, кто прибегал к рвотному или слабительному средству, у ослабленного лихорадками, у изнурённого долгим постом, у евшего несовместимую пищу или пищу поверх непереваренной; у того, кто без меры употреблял слишком солёные, щелочные, горячие, кислые и острые на вкус вещества, ел мясо кабана или барана, творог, глину; у чрезмерно предававшегося холодному ветру, телесным упражнениям и соитию; равно и у женщины, роды которой были неправильны или трудны, у которой случился выкидыш, у которой не прекращаются выделения, или которая отказывается от лечения, — от этих самых причин, а также от подобных им, быстро возникает тяжёлый (дарунья) отёк."
