        "text": "В отваре старых корней швадамштры, эранды, билвы, сухого имбиря и старой редьки следует сварить молоко; когда останется одно только молоко, его снимают с огня, а затем, прибавив гхи и сахар, доваривают на слабом, среднем и сильном огне поочерёдно. Такое гхи уничтожает ватический отёк."
