        "text": "Знай, что шула от Ваты свирепа, усиливается у голодного и в своих сильных приступах затрудняет дыхание; шула от Питты наступает после переваривания пищи и сопровождается непрестанным потением, жжением и жаждой. Знай также, что шула от Капхи наступает тотчас после еды, вялая, тупая, оцепенелая, вызывает скованность и подступающую тошноту; а четвёртая, возникающая от санипаты (совместного расстройства всех трёх дош), несёт признаки всех трёх сразу — она трудно переносима и трудноизлечима"
