        "text": "Вата, как сказано, весьма сильна и стремительна в своём натиске: возбуждённая, она быстро губит тело. Поэтому врач должен прежде всего умастить маслом больного, страдающего от ватика-шулы, и тотчас же провести сведану (прогревание)"
